1	// Package mevwatch implements mempool risk detection.
2	package mevwatch
3	
4	import (
5		"sort"
6		"strconv"
7	)
8	
9	// Swap is one observed swap in a pending or confirmed transaction.
10	type Swap struct {
11		TxHash   string
12		Pool     string
13		Trader   string
14		In       int64
15		Out      int64
16		GasPrice int64
17		Index    int
18	}
19	
20	// Finding is one risk conclusion with the evidence that produced it.
21	type Finding struct {
22		TxHash   string
23		Kind     string
24		Severity int
25		Evidence []string
26	}
27	
28	// Detect flags sandwich and displacement patterns around one victim swap.
29	func Detect(swaps []Swap, victim string) []Finding {
30		victimIndex := -1
31		for index, swap := range swaps {
32			if swap.TxHash == victim {
33				victimIndex = index
34				break
35			}
36		}
37		if victimIndex <= 0 || victimIndex >= len(swaps)-1 {
38			return nil
39		}
40		front, back := swaps[victimIndex-1], swaps[victimIndex+1]
41		if front.Trader == back.Trader && front.Pool == back.Pool && front.Trader != swaps[victimIndex].Trader &&
42			front.GasPrice > swaps[victimIndex].GasPrice && back.GasPrice > swaps[victimIndex].GasPrice {
43			return []Finding{{
44				TxHash: victim, Kind: "sandwich", Severity: 3,
45				Evidence: []string{
46					"front-run by " + front.Trader + " at gas " + strconv.FormatInt(front.GasPrice, 10),
47					"back-run by " + back.Trader + " at gas " + strconv.FormatInt(back.GasPrice, 10),
48					"victim gas " + strconv.FormatInt(swaps[victimIndex].GasPrice, 10),
49				},
50			}}
51		}
52		if front.GasPrice > swaps[victimIndex].GasPrice*2 {
53			return []Finding{{TxHash: victim, Kind: "displacement", Severity: 2,
54				Evidence: []string{"front gas dominates victim by more than 2x"}}}
55		}
56		return nil
57	}
58	
59	// Rank orders findings by severity then hash.
60	func Rank(findings []Finding) []Finding {
61		sorted := append([]Finding(nil), findings...)
62		sort.Slice(sorted, func(i, j int) bool {
63			if sorted[i].Severity == sorted[j].Severity {
64				return sorted[i].TxHash < sorted[j].TxHash
65			}
66			return sorted[i].Severity > sorted[j].Severity
67		})
68		return sorted
69	}
