3	import (
4		"reflect"
5		"testing"
6	)
7	
8	// 本文件是“多次独立调用之间不共享可变状态”的回归保障：调用方可以保留一份初始
9	// 状态和请求作为比较不同复制结果的基准，每次模拟都从传入的基准开始——实现不得
10	// 把处理后的状态写回输入，也不得让一次调用的结果与其他独立调用的输入或结果
11	// 共享可变的切片、映射或指针。
12	
13	// isolationInitial 是本文件回归场景共享的初始状态：当前任期 2，idx1
14	// （set count=10，任期 1）已提交，idx2（incr count=5，任期 2）是未提交尾部。
15	func isolationInitial() InitialState {
16		return InitialState{CurrentTerm: 2, CommittedIndex: 1, Log: []LogEntry{
17			entry(1, 1, "set count=10"),
18			entry(2, 2, "incr count=5"), // 未提交尾部：独立调用之间不得互相继承对它的替换
19		}}
20	}
21	
22	// isolationReplaceRequest 是共享的合法较高任期请求：任期 3、前置匹配 idx1，
23	// 用任期 3 的 incr count=2 替换未提交的 idx2 并提交到 2。
24	func isolationReplaceRequest() AppendRequest {
25		return AppendRequest{Term: 3, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 2,
26			Entries: []LogEntry{entry(2, 3, "incr count=2")}}
27	}
28	
29	// cloneInitial 深拷贝初始状态，用于在调用后逐字段确认输入仍保持原值。
30	func cloneInitial(initial InitialState) InitialState {
31		return InitialState{
32			CurrentTerm:    initial.CurrentTerm,
33			CommittedIndex: initial.CommittedIndex,
34			Log:            append([]LogEntry(nil), initial.Log...),
35		}
36	}
37	
38	// cloneAppendRequest 深拷贝一条请求（含条目切片），用途同 cloneInitial。
39	func cloneAppendRequest(request AppendRequest) AppendRequest {
40		clone := request
41		clone.Entries = append([]LogEntry(nil), request.Entries...)
42		return clone
43	}
44	
45	// wantIsolationReplaceOutcome 断言“替换并提交”调用的完整预期结果：已提交前缀
46	// 保留，idx2 换成 incr count=2，count 为 "12"，提交位置与应用位置都到达第二条。
47	func wantIsolationReplaceOutcome(t *testing.T, out ReplicateOutput) {
48		t.Helper()
49		if len(out.Results) != 1 {
50			t.Fatalf("got %d results, want 1", len(out.Results))
51		}
52		result := out.Results[0]
53		if !result.Accepted || result.Reason != ReasonOK {
54			t.Fatalf("legal replacement should be accepted: %+v", result)
55		}
56		if result.Term != 3 || result.CommittedIndex != 2 {
57			t.Fatalf("result state = term %d ci %d, want term 3 ci 2",
58				result.Term, result.CommittedIndex)
59		}
60		if got := appliedIndexOf(t, result); got != 2 {
61			t.Fatalf("result appliedIndex = %d, want 2", got)
62		}
63		if result.ApplyError != nil {
64			t.Fatalf("unexpected apply error: %+v", result.ApplyError)
65		}
66		wantLog := []LogEntry{
67			entry(1, 1, "set count=10"), // 已提交前缀必须保留
68			entry(2, 3, "incr count=2"),
69		}
70		if !reflect.DeepEqual(out.FinalLog, wantLog) {
71			t.Fatalf("final log = %+v, want %+v", out.FinalLog, wantLog)
72		}
73		if out.FinalTerm != 3 || out.FinalCommittedIndex != 2 {
74			t.Fatalf("final state = term %d ci %d, want term 3 ci 2",
75				out.FinalTerm, out.FinalCommittedIndex)
76		}
77		if *out.FinalAppliedIndex != 2 {
78			t.Fatalf("final appliedIndex = %d, want 2", *out.FinalAppliedIndex)
79		}
80		if kv := finalKVOf(t, out); !reflect.DeepEqual(kv, map[string]string{"count": "12"}) {
81			t.Fatalf("final kv = %v, want only count=12", kv)
82		}
83		if out.FinalApplyError != nil {
84			t.Fatalf("final apply error = %+v, want none", out.FinalApplyError)
85		}
86	}
87	
88	// wantIsolationStartOutcome 断言“从基准开始、没有任何复制请求”的完整预期结果：
89	// 未提交尾部保留，键值表只得到已提交前缀对应的 "10"，提交与应用位置停在第一条。
90	func wantIsolationStartOutcome(t *testing.T, out ReplicateOutput) {
91		t.Helper()
92		if len(out.Results) != 0 {
93			t.Fatalf("unexpected results: %+v", out.Results)
94		}
95		wantLog := []LogEntry{
96			entry(1, 1, "set count=10"),
97			entry(2, 2, "incr count=5"), // 原未提交尾部必须保留
98		}
99		if !reflect.DeepEqual(out.FinalLog, wantLog) {
100			t.Fatalf("final log = %+v, want %+v (uncommitted tail must be kept)", out.FinalLog, wantLog)
101		}
102		if out.FinalTerm != 2 || out.FinalCommittedIndex != 1 {
103			t.Fatalf("final state = term %d ci %d, want term 2 ci 1",
104				out.FinalTerm, out.FinalCommittedIndex)
105		}
106		if *out.FinalAppliedIndex != 1 {
107			t.Fatalf("final appliedIndex = %d, want 1", *out.FinalAppliedIndex)
108		}
109		if kv := finalKVOf(t, out); !reflect.DeepEqual(kv, map[string]string{"count": "10"}) {
110			t.Fatalf("final kv = %v, want only count=10 (committed prefix only)", kv)
111		}
112		if out.FinalApplyError != nil {
113			t.Fatalf("final apply error = %+v, want none", out.FinalApplyError)
114		}
115	}
116	
117	// TestReplicateCallsDoNotShareMutableState 主场景：调用方保存一份初始状态与请求
118	// 作为基准。第一次调用用 incr count=2 替换未提交条目并提交，结果保留已提交前缀、
119	// count 为 "12"、提交与应用位置都到第二条；调用结束后基准（初始任期、提交位置、
120	// 原日志、请求内容）仍保持原值。随后用同一基准发起一次没有复制请求的独立调用，
121	// 必须保留原来的未提交尾部，键值表只能得到已提交前缀对应的 "10"——不能继承前次
122	// 的替换、提交或应用进度。
123	func TestReplicateCallsDoNotShareMutableState(t *testing.T) {
124		initial := isolationInitial()
125		request := isolationReplaceRequest()
126		initialSnapshot := cloneInitial(initial)
127		requestSnapshot := cloneAppendRequest(request)
128	
129		out := runKV(t, initial, request)
130		wantIsolationReplaceOutcome(t, out)
131	
132		// 调用结束后，调用方保存的基准仍保持原值：处理后的状态不能写回输入。
133		if !reflect.DeepEqual(initial, initialSnapshot) {
134			t.Fatalf("initial state mutated by call:\n got %+v\nwant %+v", initial, initialSnapshot)
135		}
136		if !reflect.DeepEqual(request, requestSnapshot) {
137			t.Fatalf("request mutated by call:\n got %+v\nwant %+v", request, requestSnapshot)
138		}
139	
140		// 用原初始状态发起一次没有复制请求的独立调用：从基准开始，不继承前次进度。
141		fresh := runKV(t, initial)
142		wantIsolationStartOutcome(t, fresh)
143	
144		// 基准在经历两次调用后依然原样，可继续作为比较基准。
145		if !reflect.DeepEqual(initial, initialSnapshot) {
146			t.Fatalf("initial state mutated across calls:\n got %+v\nwant %+v", initial, initialSnapshot)
147		}
148	}
149	
150	// TestReplicateInputSlicesMayBeViewsIntoLargerArrays 输入日志或请求条目来自一段
151	// 更大数组的局部视图时，同样满足隔离要求：视图之外（未参与本次调用）的内容不能
152	// 受到影响，视图本身的内容也不能被写回。
153	func TestReplicateInputSlicesMayBeViewsIntoLargerArrays(t *testing.T) {
154		logBacking := []LogEntry{
155			entry(1, 1, "set logguard=before"),
156			entry(1, 1, "set count=10"),
157			entry(2, 2, "incr count=5"),
158			entry(4, 4, "set logguard=after"),
159		}
160		initial := InitialState{CurrentTerm: 2, CommittedIndex: 1, Log: logBacking[1:3]}
161		entriesBacking := []LogEntry{
162			entry(1, 1, "set reqguard=before"),
163			entry(2, 3, "incr count=2"),
164			entry(3, 3, "set reqguard=after"),
165		}
166		request := isolationReplaceRequest()
167		request.Entries = entriesBacking[1:2]
168	
169		out := runKV(t, initial, request)
170		wantIsolationReplaceOutcome(t, out)
171	
172		// 视图之外的内容不受影响。
173		if logBacking[0] != entry(1, 1, "set logguard=before") ||
174			logBacking[3] != entry(4, 4, "set logguard=after") {
175			t.Fatalf("log backing array outside the view changed: %+v", logBacking)
176		}
177		if entriesBacking[0] != entry(1, 1, "set reqguard=before") ||
178			entriesBacking[2] != entry(3, 3, "set reqguard=after") {
179			t.Fatalf("entries backing array outside the view changed: %+v", entriesBacking)
180		}
181		// 视图本身的内容也保持原值。
182		wantLogView := []LogEntry{entry(1, 1, "set count=10"), entry(2, 2, "incr count=5")}
183		if !reflect.DeepEqual(initial.Log, wantLogView) {
184			t.Fatalf("initial log view changed: %+v, want %+v", initial.Log, wantLogView)
185		}
186		wantEntriesView := []LogEntry{entry(2, 3, "incr count=2")}
187		if !reflect.DeepEqual(request.Entries, wantEntriesView) {
188			t.Fatalf("request entries view changed: %+v, want %+v", request.Entries, wantEntriesView)
189		}
190	}
191	
192	// TestReplicateOutputIsOwnedByCaller 返回结果的归属：调用方修改一次结果里的日志
193	// 命令、键值表或逐条接收结果后，不得改动缓存的输入，也不得影响其他独立调用已经
194	// 得到或之后得到的结果。
195	func TestReplicateOutputIsOwnedByCaller(t *testing.T) {
196		initial := isolationInitial()
197		first := runKV(t, initial, isolationReplaceRequest())
198		second := runKV(t, initial, isolationReplaceRequest())
199	
200		// 调用方随意改写第一份结果：日志命令、键值表、逐条接收结果。
201		first.FinalLog[0].Command = "set count=999"
202		first.FinalLog[1].Command = "incr count=999"
203		first.FinalKV["count"] = "999"
204		first.FinalKV["injected"] = "x"
205		first.Results[0].CommittedIndex = 99
206		*first.Results[0].AppliedIndex = 99
207		*first.FinalAppliedIndex = 99
208	
209		// 缓存的输入不被改动。
210		if !reflect.DeepEqual(initial, isolationInitial()) {
211			t.Fatalf("cached input changed after mutating a result: %+v", initial)
212		}
213		// 之前已经得到的另一份独立结果不受影响。
214		wantIsolationReplaceOutcome(t, second)
215		// 之后用同一基准得到的结果也不受影响。
216		third := runKV(t, initial, isolationReplaceRequest())
217		wantIsolationReplaceOutcome(t, third)
218	}
219	
220	// TestReplicateRejectionDoesNotLeakStateIntoInput 拒绝路径：用原初始状态和一条
221	// 格式合法但前置日志不匹配的较高任期请求。该次结果仍保留现有的任期更新和冲突
222	// 提示，日志仍为原来的两条，提交和应用位置停在第一条，count 仍为 "10"；任期更新
223	// 只属于该次调用，原初始状态不能被抬高任期。
224	func TestReplicateRejectionDoesNotLeakStateIntoInput(t *testing.T) {
225		initial := isolationInitial()
226		initialSnapshot := cloneInitial(initial)
227		// 前置索引存在（idx2）但声明的任期 9 与本地任期 2 不同：格式合法的前置不匹配。
228		mismatch := AppendRequest{Term: 5, PrevLogIndex: 2, PrevLogTerm: 9, LeaderCommit: 2}
229	
230		out := runKV(t, initial, mismatch)
231		if len(out.Results) != 1 {
232			t.Fatalf("got %d results, want 1", len(out.Results))
233		}
234		result := out.Results[0]
235		if result.Accepted || result.Reason != ReasonPrevLogMismatch {
236			t.Fatalf("expected prev log mismatch rejection, got %+v", result)
237		}
238		// 该次结果仍保留现有的任期更新和冲突提示。
239		if result.Term != 5 {
240			t.Fatalf("higher term should survive in this call's result: term = %d, want 5", result.Term)
241		}
242		if result.Conflict == nil || *result.Conflict != (ConflictHint{Index: 2, Term: 2}) {
243			t.Fatalf("conflict = %+v, want {2 2}", result.Conflict)
244		}
245		// 日志仍为原来的两条，提交和应用位置停在第一条。
246		if result.CommittedIndex != 1 {
247			t.Fatalf("commit moved on rejection: %d, want 1", result.CommittedIndex)
248		}
249		if got := appliedIndexOf(t, result); got != 1 {
250			t.Fatalf("applied index moved on rejection: %d, want 1", got)
251		}
252		if result.ApplyError != nil {
253			t.Fatalf("rejection must not produce an apply error: %+v", result.ApplyError)
254		}
255		if !reflect.DeepEqual(out.FinalLog, initialSnapshot.Log) {
256			t.Fatalf("log changed after rejection: %+v, want %+v", out.FinalLog, initialSnapshot.Log)
257		}
258		if out.FinalTerm != 5 || out.FinalCommittedIndex != 1 {
259			t.Fatalf("final state = term %d ci %d, want term 5 ci 1",
260				out.FinalTerm, out.FinalCommittedIndex)
261		}
262		if *out.FinalAppliedIndex != 1 {
263			t.Fatalf("final appliedIndex = %d, want 1", *out.FinalAppliedIndex)
264		}
265		if kv := finalKVOf(t, out); !reflect.DeepEqual(kv, map[string]string{"count": "10"}) {
266			t.Fatalf("final kv = %v, want only count=10", kv)
267		}
268		if out.FinalApplyError != nil {
269			t.Fatalf("final apply error = %+v, want none", out.FinalApplyError)
270		}
271	
272		// 任期更新只属于该次调用：原初始状态不能被抬高任期，其余字段同样原样。
273		if initial.CurrentTerm != 2 {
274			t.Fatalf("initial term raised by a rejected call: %d, want 2", initial.CurrentTerm)
275		}
276		if !reflect.DeepEqual(initial, initialSnapshot) {
