903		if result.Accepted || result.Reason != ReasonStaleTerm {
904			t.Fatalf("expected stale-term rejection, got %+v", result)
905		}
906		if result.Conflict != nil {
907			t.Fatalf("stale-term rejection must not carry conflict: %+v", result.Conflict)
908		}
909		if result.Term != 2 || result.CommittedIndex != 1 {
910			t.Fatalf("state changed: %+v", result)
911		}
912		if !reflect.DeepEqual(out.FinalLog, initial.Log) {
913			t.Fatalf("log changed: %+v", out.FinalLog)
914		}
915	}
916	
917	// TestFirstEntryTermBridgeFieldErrorThenValidRecovery 非法衔接请求被拒后节点保持
918	// 原状态，随后到达的合法请求按原状态继续处理：任期 3、正确匹配索引 2，追加索引
919	// 3、任期 2 的条目并提交到 3。
920	func TestFirstEntryTermBridgeFieldErrorThenValidRecovery(t *testing.T) {
921		initial := InitialState{CurrentTerm: 2, CommittedIndex: 1, Log: []LogEntry{
922			entry(1, 1, "set balance=100"),
923			entry(2, 2, "set balance=200"),
924		}}
925		bad := AppendRequest{Term: 7, PrevLogIndex: 2, PrevLogTerm: 2, LeaderCommit: 9,
926			Entries: []LogEntry{entry(3, 1, "set evil=1")}}
927		legal := AppendRequest{Term: 3, PrevLogIndex: 2, PrevLogTerm: 2, LeaderCommit: 3,
928			Entries: []LogEntry{entry(3, 2, "set receipt=ok")}}
929		out := run(t, initial, bad, legal)
930	
931		first := out.Results[0]
932		if first.Accepted || first.Reason != ReasonEntryTermDecreases {
933			t.Fatalf("first request should be the term-bridge field error, got %+v", first)
934		}
935		if first.Conflict != nil || first.Term != 2 || first.CommittedIndex != 1 {
936			t.Fatalf("first request changed state: %+v", first)
937		}
938		second := out.Results[1]
939		if !second.Accepted || second.Reason != ReasonOK {
940			t.Fatalf("valid follow-up request must be processed from the original state: %+v", second)
941		}
942		if second.Term != 3 || second.CommittedIndex != 3 {
943			t.Fatalf("second result state = term %d ci %d, want term 3 ci 3",
944				second.Term, second.CommittedIndex)
945		}
946		want := []LogEntry{
947			entry(1, 1, "set balance=100"),
948			entry(2, 2, "set balance=200"),
949			entry(3, 2, "set receipt=ok"),
950		}
951		if !reflect.DeepEqual(out.FinalLog, want) {
952			t.Fatalf("final log = %+v, want %+v", out.FinalLog, want)
953		}
954		if out.FinalTerm != 3 || out.FinalCommittedIndex != 3 {
955			t.Fatalf("final state = term %d ci %d, want term 3 ci 3",
956				out.FinalTerm, out.FinalCommittedIndex)
957		}
958	}
959	
960	// conflict 只在前置日志不匹配的结果里出现在 JSON 中，其余结果不输出该键。
961	func TestConflictHintJSONShape(t *testing.T) {
962		out := run(t, InitialState{CurrentTerm: 2, Log: []LogEntry{entry(1, 2, "a")}},
963			AppendRequest{Term: 2, PrevLogIndex: 1, PrevLogTerm: 2},
964			AppendRequest{Term: 2, PrevLogIndex: 3, PrevLogTerm: 2},
965		)
966		encoded, err := json.Marshal(out.Results[0])
967		if err != nil {
968			t.Fatal(err)
969		}
970		if strings.Contains(string(encoded), "conflict") {
971			t.Fatalf("accepted result should omit conflict, got %s", encoded)
972		}
973		encoded, err = json.Marshal(out.Results[1])
974		if err != nil {
975			t.Fatal(err)
976		}
977		var decoded map[string]any
978		if err := json.Unmarshal(encoded, &decoded); err != nil {
979			t.Fatal(err)
980		}
981		conflict, ok := decoded["conflict"].(map[string]any)
982		if !ok {
983			t.Fatalf("mismatch result should carry conflict object, got %s", encoded)
984		}
985		if conflict["index"] != float64(2) || conflict["term"] != float64(0) {
986			t.Fatalf("conflict = %v, want index 2 term 0", conflict)
987		}
988		// 编解码往返后反馈保持原样。
989		var roundTrip AppendResult
