354	// roundTrip 把输出编码为 JSON 再解码、再编码，模拟调用方保存或转交结果。
355	func roundTrip(t *testing.T, out ReplicateOutput) (ReplicateOutput, string) {
356		t.Helper()
357		encoded, err := json.Marshal(out)
358		if err != nil {
359			t.Fatal(err)
360		}
361		var decoded ReplicateOutput
362		if err := json.Unmarshal(encoded, &decoded); err != nil {
363			t.Fatal(err)
364		}
365		reencoded, err := json.Marshal(decoded)
366		if err != nil {
367			t.Fatal(err)
368		}
369		return decoded, string(reencoded)
370	}
