673	// TestKVRoundTripApplyLevelsIndependent 两层应用字段各自按本层是否出现判断：
674	// 最终结果记录了应用状态，不能让没有应用字段的请求答复凭空多出应用信息；某条
675	// 请求带有应用字段，也不能让最终结果或其他请求多出字段。同一输出中混合两种
676	// 请求答复时，读取再输出必须保留各自区别。
677	func TestKVRoundTripApplyLevelsIndependent(t *testing.T) {
678		perRequestKeys := []string{"appliedIndex", "applyError"}
679		finalKeys := []string{"finalAppliedIndex", "finalKV", "finalApplyError"}
680		cases := []struct {
681			name string
682			data string
683		}{
684			{
685				"final level applied, requests mixed plain and applied",
686				`{"results":[` +
687					`{"accepted":true,"reason":"ok","term":3,"committedIndex":0},` +
688					`{"accepted":false,"reason":"stale term: leader term is lower than current term","term":3,"committedIndex":0,"appliedIndex":2,"applyError":{"index":3,"reason":"boom"}}` +
689					`],"finalTerm":3,"finalCommittedIndex":0,"finalLog":[],` +
690					`"finalAppliedIndex":2,"finalKV":{"k":"v"},"finalApplyError":{"index":3,"reason":"boom"}}`,
691			},
692			{
693				"final level absent, requests mixed applied and plain",
694				`{"results":[` +
695					`{"accepted":true,"reason":"ok","term":1,"committedIndex":0,"appliedIndex":0,"applyError":null},` +
696					`{"accepted":true,"reason":"ok","term":1,"committedIndex":0}` +
697					`],"finalTerm":1,"finalCommittedIndex":0,"finalLog":[]}`,
698			},
699		}
700		for _, tc := range cases {
701			t.Run(tc.name, func(t *testing.T) {
702				var out ReplicateOutput
703				if err := json.Unmarshal([]byte(tc.data), &out); err != nil {
704					t.Fatal(err)
705				}
706				reencoded, err := json.Marshal(out)
707				if err != nil {
708					t.Fatal(err)
709				}
710				m := decodeMap(t, reencoded)
711				results := resultMaps(t, m)
712				if len(results) != 2 {
713					t.Fatalf("expected 2 results, got %d", len(results))
714				}
715				if strings.Contains(tc.data, `"finalAppliedIndex":2`) {
716					// 第一种情形：最终层有应用字段；请求 0 无、请求 1 有。
717					mustLackKeys(t, results[0], "plain request", perRequestKeys...)
718					mustHaveKeys(t, results[1], "applied request", perRequestKeys...)
719					if results[1]["appliedIndex"] != float64(2) {
720						t.Fatalf("request appliedIndex changed: %v", results[1])
721					}
722					if !reflect.DeepEqual(results[1]["applyError"],
723						map[string]any{"index": float64(3), "reason": "boom"}) {
724						t.Fatalf("request applyError changed: %v", results[1])
725					}
726					mustHaveKeys(t, m, "final output", finalKeys...)
727					if !reflect.DeepEqual(m["finalKV"], map[string]any{"k": "v"}) {
728						t.Fatalf("finalKV changed: %v", m["finalKV"])
729					}
730				} else {
731					// 第二种情形：最终层无应用字段；请求 0 有、请求 1 无。
732					mustHaveKeys(t, results[0], "applied request", perRequestKeys...)
733					if results[0]["appliedIndex"] != float64(0) || results[0]["applyError"] != nil {
734						t.Fatalf("applied request values changed: %v", results[0])
735					}
736					mustLackKeys(t, results[1], "plain request", perRequestKeys...)
737					mustLackKeys(t, m, "final output", finalKeys...)
738				}
739			})
740		}
741	}
