1488				}
1489				if m["appliedIndex"] != tc.wantIndex {
1490					t.Fatalf("appliedIndex = %v, want %v: %v", m["appliedIndex"], tc.wantIndex, m)
1491				}
1492				if tc.wantError == nil {
1493					if m["applyError"] != nil {
1494						t.Fatalf("applyError = %v, want null: %v", m["applyError"], m)
1495					}
1496				} else if !reflect.DeepEqual(m["applyError"], tc.wantError) {
1497					t.Fatalf("applyError = %v, want %v", m["applyError"], tc.wantError)
1498				}
1499				// 复制答复的既有字段不被大小写变体干扰。
1500				if m["accepted"] != true || m["reason"] != "ok" ||
1501					m["term"] != float64(2) || m["committedIndex"] != float64(1) {
1502					t.Fatalf("replication fields changed: %v", m)
1503				}
1504			})
1505		}
1506	}
