1697			`{"results":[{"accepted":true,"reason":"ok","term":1,"committedIndex":0,"APPLIEDINDEX":"0"}],"finalTerm":1,"finalCommittedIndex":0,"finalLog":[]}`,
1698			`{"results":[{"accepted":true,"reason":"ok","term":1,"committedIndex":0,"ApplyError":{"index":"2","reason":"x"}}],"finalTerm":1,"finalCommittedIndex":0,"finalLog":[]}`,
1699		}
1700		for _, data := range badInputs {
1701			var out ReplicateOutput
1702			if err := json.Unmarshal([]byte(data), &out); err == nil {
1703				t.Fatalf("expected decode error for %s", data)
1704			}
1705		}
1706	}
1707	
1708	// TestKVRoundTripCaseFoldedFailedReuseKeepsPreviousResult 复用已有结果对象读入
1709	// 大小写变体字段名的非法 JSON 时必须报错，并完整保留读入前的结果（含其应用
1710	// 状态）；之后输出不能混入这次读入的任何内容，也不能被变体名打开开关。
1711	func TestKVRoundTripCaseFoldedFailedReuseKeepsPreviousResult(t *testing.T) {
1712		original := runKV(t, InitialState{CurrentTerm: 1, CommittedIndex: 1, Log: []LogEntry{
1713			entry(1, 1, "set x=1"),
1714		}},
1715			AppendRequest{Term: 1, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 3,
1716				Entries: []LogEntry{entry(2, 1, "set bad"), entry(3, 1, "set k=v")}},
1717		)
1718		originalJSON, err := json.Marshal(original)
1719		if err != nil {
1720			t.Fatal(err)
1721		}
1722		badInputs := []string{
1723			// 错误位于某条请求答复内，字段名大写。
1724			`{"results":[{"accepted":true,"reason":"ok","term":9,"committedIndex":9,"APPLIEDINDEX":"3"}],"finalTerm":9,"finalCommittedIndex":9,"finalLog":[]}`,
1725			// 最终层：应用索引写成字符串，字段名首字母大写。
1726			`{"results":[],"finalTerm":9,"finalCommittedIndex":9,"finalLog":[],"FinalAppliedIndex":"9"}`,
1727			// 最终层：键值表写成数组，字段名全大写。
1728			`{"results":[],"finalTerm":9,"finalCommittedIndex":9,"finalLog":[],"FINALKV":["nope"]}`,
1729		}
1730		for _, bad := range badInputs {
1731			var out ReplicateOutput
1732			if err := json.Unmarshal(originalJSON, &out); err != nil {
1733				t.Fatal(err)
1734			}
1735			if err := json.Unmarshal([]byte(bad), &out); err == nil {
1736				t.Fatalf("expected decode error for %s", bad)
1737			}
1738			reencoded, err := json.Marshal(out)
1739			if err != nil {
1740				t.Fatal(err)
1741			}
1742			if string(reencoded) != string(originalJSON) {
1743				t.Fatalf("previous result not preserved after failed decode of %s:\nwant %s\n got %s",
1744					bad, originalJSON, reencoded)
1745			}
1746		}
1747	}
1748	
1749	// TestKVRoundTripCaseFoldedSuccessfulReuseNoResidue 复用结果对象成功读入下一份
1750	// JSON 时只保留本次内容：先读入以变体名记录应用状态的结果，再读入完全没有
1751	// 应用字段的旧结果，后一次输出不得残留前一次的键值表、错误或应用位置；反方向
1752	// （先旧后变体）则必须按本次内容补齐完整应用字段。
1753	func TestKVRoundTripCaseFoldedSuccessfulReuseNoResidue(t *testing.T) {
1754		variantApplied := `{"results":[{"accepted":true,"reason":"ok","term":1,` +
1755			`"committedIndex":1,"AppliedIndex":1,"ApplyError":null}],` +
1756			`"finalTerm":1,"finalCommittedIndex":1,` +
1757			`"finalLog":[{"index":1,"term":1,"command":"set x=1"}],` +
1758			`"FinalAppliedIndex":1,"FinalKV":{"x":"1"},"FINALAPPLYERROR":null}`
1759		plain := `{"results":[{"accepted":true,"reason":"ok","term":1,"committedIndex":1}],` +
1760			`"finalTerm":1,"finalCommittedIndex":1,` +
1761			`"finalLog":[{"index":1,"term":1,"command":"set x=1"}]}`
1762	
1763		// 先变体后旧结果：无残留。
1764		var out ReplicateOutput
1765		if err := json.Unmarshal([]byte(variantApplied), &out); err != nil {
1766			t.Fatal(err)
1767		}
1768		if err := json.Unmarshal([]byte(plain), &out); err != nil {
1769			t.Fatal(err)
1770		}
1771		body, err := json.Marshal(out)
1772		if err != nil {
1773			t.Fatal(err)
1774		}
1775		for _, field := range []string{"appliedIndex", "applyError", "finalAppliedIndex", "finalKV", "finalApplyError"} {
1776			if strings.Contains(string(body), field) {
1777				t.Fatalf("stale apply field %q after reusing object: %s", field, body)
1778			}
1779		}
1780		if out.FinalKV != nil || out.FinalAppliedIndex != nil || out.FinalApplyError != nil {
1781			t.Fatalf("stale apply state in %+v", out)
1782		}
1783	
1784		// 先旧结果后变体：按本次内容带齐标准字段。
1785		var out2 ReplicateOutput
1786		if err := json.Unmarshal([]byte(plain), &out2); err != nil {
1787			t.Fatal(err)
1788		}
1789		if err := json.Unmarshal([]byte(variantApplied), &out2); err != nil {
1790			t.Fatal(err)
1791		}
1792		body2, err := json.Marshal(out2)
1793		if err != nil {
1794			t.Fatal(err)
1795		}
1796		m := decodeMap(t, body2)
1797		mustHaveKeys(t, m, "final output",
1798			"finalAppliedIndex", "finalKV", "finalApplyError")
1799		if m["finalAppliedIndex"] != float64(1) ||
1800			!reflect.DeepEqual(m["finalKV"], map[string]any{"x": "1"}) ||
1801			m["finalApplyError"] != nil {
1802			t.Fatalf("variant-keyed apply state not restored after reuse: %v", m)
1803		}
1804		results := resultMaps(t, m)
1805		mustHaveKeys(t, results[0], "applied request", "appliedIndex", "applyError")
1806	}
1807

